// Leaderboard data is loaded from scores.json (generated by
// inverse-strategy/plotting/paper/generate_scores.py).
//
// Schema:
//   { schema_version, generated_at, arenas, models:[{slug,name,scores,n_runs}] }

let leaderboardData = [];

function arenaMean(scores) {
    const vals = arenas.map(a => scores[a.key]).filter(v => typeof v === "number");
    if (!vals.length) return 0;
    return vals.reduce((a, b) => a + b, 0) / vals.length;
}

function buildLeaderboardData(models) {
    const enriched = models.map(row => ({
        ...row,
        avg: arenaMean(row.scores)
    }));
    enriched.sort((a, b) => b.avg - a.avg);
    leaderboardData = enriched.map((row, i) => ({ ...row, rank: i + 1 }));
}

async function loadScoresData() {
    const res = await fetch('scores.json');
    if (!res.ok) throw new Error(`scores.json: ${res.status}`);
    const data = await res.json();
    buildLeaderboardData(data.models);
    return data;
}
